-- Rollback-only distinct-user acceptance checks. Run only through run-local.mjs.
begin;
create function pg_temp.assert_world(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'WORLD TEST FAILED: %',label;end if;end$$;
create function pg_temp.denied(statement text,expected text default '42501') returns void language plpgsql as $$
begin
 begin execute statement;exception when others then
  if sqlstate=expected then return;end if;raise exception 'Expected %, got % (%) for %',expected,sqlstate,sqlerrm,statement;
 end;raise exception 'WORLD TEST FAILED: permitted %',statement;
end$$;
